import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for unsent invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.startsWith('DRAFT'));
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  const text = renderInvoiceText(r2.value);
  assert.ok(text.startsWith('INV-2023-0001'));
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText formats line items with proper structure', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.ok(lines[2].includes('5 x'));
  assert.ok(lines[2].includes('Design work (hour)'));
  assert.ok(lines[2].includes('€85.00'));
  assert.ok(lines[2].includes('€425.00'));
});

test('renderInvoiceText formats prices with formatEuros', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // STICKER unitPrice is 50 cents, qty is 100, so line total is 5000 cents = €50.00
  assert.ok(lines[2].includes('€0.50'));
  assert.ok(lines[2].includes('€50.00'));
});

test('renderInvoiceText includes total line', () => {
  const r = createInvoice({
    customerId: 'C-002', // Standard tier (0% discount)
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const totalLine = lines.find(l => l.startsWith('Total:'));
  assert.ok(totalLine);
  // 5 * 8500 = 42500, VAT: 8925, Total: 51425
  assert.ok(totalLine.includes('€514.25'));
});

test('renderInvoiceText handles multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-002', // Standard tier (0% discount)
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 3 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Line structure: DRAFT, customer, 3 items, VAT, total, due = 8 lines
  assert.equal(lines.length, 8);
  assert.ok(lines[2].includes('Design work (hour)'));
  assert.ok(lines[3].includes('Copywriting (hour)'));
  assert.ok(lines[4].includes('Icon set (24 icons)'));
  // Subtotal: 5*8500 + 2*6000 + 3*980 = 57440
  // VAT: 42500*0.21 + 12000*0.21 + 2940*0.21 = 8925 + 2520 + 617.4 = 12062.4, rounded = 12062
  // Total: 57440 + 12062 = 69502
  const totalLine = lines.find(l => l.startsWith('Total:'));
  assert.ok(totalLine.includes('€695.02'));
});

test('renderInvoiceText calculates correct totals', () => {
  const r = createInvoice({
    customerId: 'C-002', // Standard tier (0% discount)
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Subtotal: 10*8500 + 5*9500 = 85000 + 47500 = 132500
  // DES-HOUR (qty=10): bulk discount: 85000*0.025 = 2125, after: 82875, VAT: 82875*0.21 = 17403.75 -> 17404
  // DEV-HOUR (qty=5): no bulk discount, VAT: 47500*0.21 = 9975
  // Total discount: 2125, Total VAT: 17404 + 9975 = 27379
  // Total: 132500 - 2125 + 27379 = 157754 = €1,577.54
  const totalLine = lines.find(l => l.startsWith('Total:'));
  assert.ok(totalLine.includes('€1,577.54'));
});

test('renderInvoiceText clamps negative totals at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: -5,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // -5 * 8500 = -42500, but clamped at 0
  assert.ok(lines[2].includes('-5 x'));
  assert.ok(lines[2].includes('-€425.00'));
  assert.ok(lines[lines.length - 1].includes('€0.00'));
});

